<template>
  <div class="chamados-page">
    <header class="page-header"><div><span>ATENDIMENTO PÚBLICO</span><h1>Chamados de clientes</h1><p>Solicitações enviadas pelo portal e WhatsApp, integradas ao CRM e prontas para orçamento.</p></div><button class="refresh" :disabled="loading" @click="carregar"><ArrowPathIcon :class="{ spin: loading }" /> Atualizar</button></header>
    <section class="filters"><input v-model.trim="busca" placeholder="Buscar por protocolo, cliente, telefone ou demanda" @keyup.enter="carregar" /><select v-model="status" @change="carregar"><option value="">Todos os status</option><option value="recebido">Recebidos</option><option value="em_triagem">Em triagem</option><option value="orcamento_em_preparo">Orçamento em preparo</option><option value="aguardando_autorizacao">Aguardando autorização</option><option value="autorizado">Autorizados</option><option value="cancelado">Cancelados</option></select><button @click="carregar">Filtrar</button></section>
    <div class="workspace">
      <section class="list card"><p v-if="loading" class="empty">Carregando chamados...</p><p v-else-if="!chamados.length" class="empty">Nenhum chamado encontrado.</p><button v-for="item in chamados" :key="item.id" :class="['ticket', selecionado?.id===item.id && 'active']" @click="abrir(item.id)"><div><b>{{ item.protocolo }}</b><span>{{ item.nome }}</span><small>{{ item.tipo_demanda }}</small></div><div class="ticket-side"><span :class="['tag',item.status]">{{ label(item.status) }}</span><small>{{ data(item.created_at) }}</small></div></button><footer v-if="meta.last_page>1"><button :disabled="meta.current_page<=1" @click="pagina--;carregar()">Anterior</button><span>{{ meta.current_page }} / {{ meta.last_page }}</span><button :disabled="meta.current_page>=meta.last_page" @click="pagina++;carregar()">Próxima</button></footer></section>
      <section class="detail card"><div v-if="!selecionado" class="empty">Selecione um chamado para ver os dados e preparar o orçamento.</div><template v-else><div class="detail-head"><div><span class="eyebrow">{{ selecionado.protocolo }}</span><h2>{{ selecionado.nome }}</h2><p>{{ selecionado.tipo_demanda }} · {{ selecionado.telefone }}</p></div><span :class="['tag',selecionado.status]">{{ label(selecionado.status) }}</span></div><div class="client-data"><span><b>E-mail</b>{{ selecionado.email || 'Não informado' }}</span><span><b>Cliente</b>{{ selecionado.cliente?.razao_social || selecionado.nome }}</span><span><b>CRM</b>{{ selecionado.lead?.titulo || 'Lead não vinculado' }}</span></div><article><h3>Descrição da demanda</h3><p>{{ selecionado.descricao }}</p><small v-if="selecionado.dados?.melhor_horario">Melhor horário: {{ selecionado.dados.melhor_horario }}</small></article>
        <form v-if="!['autorizado','cancelado'].includes(selecionado.status)" class="quote" @submit.prevent="salvarOrcamento"><div><span class="eyebrow">Orçamento para o cliente</span><h3>Preparar proposta</h3><p>Ao salvar, o sistema libera o link de autorização. Copie a mensagem do WhatsApp para enviar ao cliente.</p></div><label>Título<input v-model.trim="form.orcamento_titulo" required maxlength="200" /></label><label>Escopo e condições<textarea v-model.trim="form.orcamento_descricao" required minlength="15" rows="5" maxlength="6000" /></label><div class="quote-grid"><label>Valor (R$)<input v-model.number="form.orcamento_valor" required type="number" min="0.01" step="0.01" /></label><label>Válido até<input v-model="form.orcamento_validade" required type="date" :min="hoje" /></label></div><p v-if="erro" class="error">{{ erro }}</p><button class="primary" :disabled="saving">{{ saving?'Salvando...':'Liberar para autorização' }}</button></form>
        <div v-else class="final-state"><CheckCircleIcon /><div><b>{{ selecionado.status==='autorizado'?'Serviço autorizado':'Chamado cancelado' }}</b><p v-if="selecionado.contrato?.numero">Contrato {{ selecionado.contrato.numero }} gerado pelo aceite eletrônico.</p></div></div>
        <div v-if="linkCliente" class="share"><b>Link pronto para o cliente</b><input :value="linkCliente" readonly @focus="$event.target.select()" /><div><button @click="copiar(linkCliente)">Copiar link</button><a :href="whatsappUrl" target="_blank" rel="noopener">Abrir WhatsApp</a></div></div>
      </template></section>
    </div>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ArrowPathIcon, CheckCircleIcon } from '@heroicons/vue/24/outline'
import { useToast } from 'vue-toastification'
import api from '@/services/api'
const toast=useToast(); const chamados=ref([]),selecionado=ref(null),loading=ref(false),saving=ref(false),busca=ref(''),status=ref(''),pagina=ref(1),meta=reactive({current_page:1,last_page:1}),erro=ref(''),linkCliente=ref(''),whatsappUrl=ref('');const hoje=new Date().toISOString().slice(0,10)
const form=reactive({orcamento_titulo:'',orcamento_descricao:'',orcamento_valor:null,orcamento_validade:''})
const labels={recebido:'Recebido',em_triagem:'Em triagem',orcamento_em_preparo:'Em preparo',aguardando_autorizacao:'Aguardando aceite',autorizado:'Autorizado',cancelado:'Cancelado'}; const label=value=>labels[value]||value; const data=value=>value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—'
async function carregar(){loading.value=true;try{const {data}=await api.get('/chamados-clientes',{params:{busca:busca.value,status:status.value,page:pagina.value,per_page:20}});chamados.value=data.data||[];Object.assign(meta,{current_page:data.current_page||1,last_page:data.last_page||1})}catch{toast.error('Não foi possível carregar os chamados.')}finally{loading.value=false}}
async function abrir(id){linkCliente.value='';whatsappUrl.value='';try{const {data}=await api.get(`/chamados-clientes/${id}`);selecionado.value=data.data;Object.assign(form,{orcamento_titulo:selecionado.value.orcamento_titulo||`Proposta para ${selecionado.value.tipo_demanda}`,orcamento_descricao:selecionado.value.orcamento_descricao||selecionado.value.descricao||'',orcamento_valor:selecionado.value.orcamento_valor||null,orcamento_validade:selecionado.value.orcamento_validade||''})}catch{toast.error('Não foi possível abrir este chamado.')}}
async function salvarOrcamento(){if(!selecionado.value)return;saving.value=true;erro.value='';try{const {data}=await api.put(`/chamados-clientes/${selecionado.value.id}/orcamento`,form);selecionado.value=data.data;linkCliente.value=data.link_cliente;whatsappUrl.value=data.whatsapp_url;toast.success('Orçamento liberado para autorização do cliente.');carregar()}catch(e){erro.value=e.response?.data?.message||Object.values(e.response?.data?.errors||{})[0]?.[0]||'Não foi possível salvar o orçamento.'}finally{saving.value=false}}
async function copiar(texto){try{await navigator.clipboard.writeText(texto);toast.success('Link copiado.')}catch{toast.info('Selecione o link e copie manualmente.')}}watch([busca,status],()=>{pagina.value=1});onMounted(carregar)
</script>

<style scoped>
.chamados-page{max-width:1450px;margin:auto;padding:24px;color:#e8edf7}.page-header{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:20px}.page-header>div>span,.eyebrow{font-size:10px;color:#58c278;letter-spacing:.14em;font-weight:800}.page-header h1{font-size:28px;font-weight:850;margin:5px 0}.page-header p{color:#8794a9;font-size:13px}.refresh,.filters button,.share button,.share a{padding:10px 13px;border:1px solid #3b465e;border-radius:8px;font-weight:800;font-size:12px}.refresh{display:flex;gap:7px;align-items:center}.refresh svg{width:17px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.filters{display:grid;grid-template-columns:1fr 180px auto;gap:10px;background:#111424;border:1px solid #292e45;border-radius:12px;padding:12px;margin-bottom:16px}.filters input,.filters select,.quote input,.quote textarea,.share input{width:100%;background:#0a0d19;color:#edf2fb;border:1px solid #30364e;padding:10px 12px;border-radius:8px;font:inherit}.filters button,.primary{background:#5d5fef;color:#fff;border-color:#5d5fef}.workspace{display:grid;grid-template-columns:minmax(310px,.82fr) minmax(0,1.35fr);gap:16px}.card{background:#111424;border:1px solid #292e45;border-radius:14px}.list{min-height:600px;overflow:hidden}.ticket{width:100%;display:flex;justify-content:space-between;gap:14px;text-align:left;padding:14px;border-bottom:1px solid #242a40}.ticket:hover,.ticket.active{background:#1a1e34}.ticket b,.ticket span,.ticket small{display:block}.ticket b{color:#b9c3ff;font-size:11px}.ticket span{font-weight:800;font-size:13px;margin:2px 0}.ticket small{color:#7e8ba1;font-size:10px}.ticket-side{text-align:right}.tag{display:inline-flex;padding:4px 7px;border-radius:999px;font-size:9px;font-weight:800;background:#283143;color:#aeb8c9;white-space:nowrap}.tag.aguardando_autorizacao{background:#6a4e172c;color:#f6c55a}.tag.autorizado{background:#17653642;color:#5ee58a}.tag.cancelado{background:#762b3442;color:#ff8794}.list footer{display:flex;justify-content:center;gap:12px;padding:14px;color:#8190a6;font-size:12px}.list footer button{color:#b3bdf5}.detail{padding:24px}.empty{color:#8290a7;padding:35px;text-align:center}.detail-head{display:flex;justify-content:space-between;gap:16px;border-bottom:1px solid #293047;padding-bottom:16px}.detail-head h2{font-size:22px;font-weight:850;margin:3px 0}.detail-head p{font-size:12px;color:#8290a6}.client-data{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:16px 0}.client-data span{padding:10px;background:#0c0f1c;border-radius:8px;color:#9ca8bb;font-size:11px;overflow-wrap:anywhere}.client-data b{display:block;color:#65728a;font-size:9px;text-transform:uppercase;margin-bottom:4px}.detail article{background:#0c0f1c;border-radius:10px;padding:14px;margin:15px 0}.detail article h3,.quote h3{font-weight:800}.detail article p{white-space:pre-line;color:#aeb9c8;font-size:12px;line-height:1.55;margin:7px 0}.detail article small{color:#7c8aa2}.quote{border-top:1px solid #293047;padding-top:20px;margin-top:20px}.quote>div>p{font-size:11px;color:#8090a5;margin:5px 0 14px}.quote label{display:block;font-size:11px;font-weight:750;color:#b4c0d2;margin-top:11px}.quote label input,.quote label textarea{margin-top:6px}.quote-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.primary{width:100%;padding:11px;border-radius:8px;font-weight:850;margin-top:14px}.error{color:#ff828e;font-size:11px;margin-top:9px}.final-state{display:flex;gap:12px;align-items:center;margin-top:24px;background:#123b2440;border:1px solid #23683a;padding:16px;border-radius:10px;color:#62e38c}.final-state svg{width:26px}.final-state p{font-size:11px;color:#a2d8b1;margin-top:3px}.share{margin-top:18px;border:1px solid #405a98;background:#202443;padding:15px;border-radius:10px}.share b{font-size:12px}.share input{margin:9px 0}.share div{display:flex;gap:8px}.share a{background:#5d5fef;color:white;text-decoration:none}.share button{background:#10142a}@media(max-width:900px){.workspace{grid-template-columns:1fr}.list{min-height:auto;max-height:420px;overflow-y:auto}.detail{padding:17px}.client-data{grid-template-columns:1fr}.filters{grid-template-columns:1fr}.page-header{flex-direction:column}}@media(max-width:480px){.chamados-page{padding:14px}.detail-head{flex-direction:column}.quote-grid{grid-template-columns:1fr}.share div{flex-direction:column}}
</style>
